import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class QualityGate {
    static String verdict(int flakeRate, int feedbackMin, int passRate) {
        if (flakeRate > 5) return "RED:flake";
        if (feedbackMin > 15) return "RED:feedback";
        if (passRate < 95) return "RED:passrate";
        return "GREEN";
    }
}

public class QualityGateTest {
    @Test
    void green() { assertEquals("GREEN", QualityGate.verdict(3, 12, 98)); }
    @Test
    void redFlake() { assertEquals("RED:flake", QualityGate.verdict(9, 12, 98)); }
    @Test
    void redFeedback() { assertEquals("RED:feedback", QualityGate.verdict(2, 40, 99)); }
    @Test
    void redPassrate() { assertEquals("RED:passrate", QualityGate.verdict(2, 12, 90)); }
}
